from otree.api import Currency as c, currency_range
from . import models
from ._builtin import Page, WaitPage
from .models import Constants
from django.utils.translation import ugettext as _


# task progress
# --------------------------------------------------------------------------------------------------------------------
task = 5
task_total = 6
task_progress = task / task_total * 100


# variables for all templates
# ----------------------------------------------------------------------------------------------------------------
def vars_for_all_templates(self):
    return {
        'task':             task,
        'task_total':       task_total,
        'task_progress':    task_progress,
        'total':            2,
        'progress':         100,
        'subject_pool':     self.participant.vars['subject_pool'],
        'treatment':        self.participant.vars['treatment'],
    }


# ******************************************************************************************************************** #
# *** CLASS TASK PROGRESS
# ******************************************************************************************************************** #
class p0_TaskProgress(Page):

    # only display in round 1
    # ----------------------------------------------------------------------------------------------------------------
    def is_displayed(self):
        return self.subsession.round_number == 1

    # timeout
    # ----------------------------------------------------------------------------------------------------------------
    timeout_seconds = 5


# ******************************************************************************************************************** #
# *** CLASS INSTRUCTIONS
# ******************************************************************************************************************** #
class p1_Instructions(Page):
    pass


# ******************************************************************************************************************** #
# *** PAGE NUMERACY *** #
# ******************************************************************************************************************** #
class p2_Numeracy(Page):

    # timeout
    # ----------------------------------------------------------------------------------------------------------------
    timeout_seconds = 240

    # form model and fields
    # ----------------------------------------------------------------------------------------------------------------
    form_model = 'player'
    form_fields = Constants.items

    # variables for template
    # ----------------------------------------------------------------------------------------------------------------
    def vars_for_template(self):
        return {
            'page':         1,
            'inventory':    self.player.participant.vars['inventory']
        }

    # set numeracy score
    # ----------------------------------------------------------------------------------------------------------------
    def before_next_page(self):
        self.player.set_numeracy_score()


# ******************************************************************************************************************** #
# *** PAGE CONFIDENCE *** #
# ******************************************************************************************************************** #
class p3_Confidence(Page):

    # form model and fields
    # ----------------------------------------------------------------------------------------------------------------
    form_model = 'player'
    form_fields = [
        'correct',
        'percentile'
    ]

    # variables for template
    # ----------------------------------------------------------------------------------------------------------------
    def vars_for_template(self):
        return {
            'page':     2
        }


# ******************************************************************************************************************** #
# *** PAGE SEQUENCE *** #
# ******************************************************************************************************************** #
page_sequence = [
    p0_TaskProgress,
    p1_Instructions,
    p2_Numeracy,
    p3_Confidence
]
